// Convert record times into chronological hourly buckets in the fixed 24-hour observation window.
export function observationBucket(article: Article, buckets = 24) {
  const elapsed =
    Date.parse(article.observedAt) - (snapshotEpoch - 24 * 3600000);
  return Math.max(
    0,
    Math.min(buckets - 1, Math.floor(elapsed / ((24 * 3600000) / buckets))),
  );
}

export const riskThresholds = {
  growth: 20,
  negative: 35,
  moderateGrowth: 10,
  moderateNegative: 25,
};

export const topics: Topic[] = topicSeeds.map((seed) => {
  const records = articles.filter((a) => a.topicId === seed.id);
  const count = records.length;
  const negative = Number(
    (
      (records.filter((a) => a.sentiment === "负面").length / count) *
      100
    ).toFixed(1),
  );
  const change = Number(
    (((count - seed.previousCount) / seed.previousCount) * 100).toFixed(1),
  );
  const trend = Array.from(
    { length: 12 },
    (_, i) => records.filter((a) => observationBucket(a, 12) === i).length,
  );
  return {
    id: seed.id,
    title: seed.title,
    category: seed.category,
    count,
    previousCount: seed.previousCount,
    change,
    negative,
    risk:
      change >= riskThresholds.growth && negative >= riskThresholds.negative
        ? "高风险"
        : change >= riskThresholds.moderateGrowth ||
            negative >= riskThresholds.moderateNegative
          ? "中风险"
          : "低风险",
    summary: seed.summary,
    keywords: seed.keywords,
    trend,
  };
});

